const MonolithCountdownTimer = ({ activatedAt }) => {
    const [timeLeft, setTimeLeft] = React.useState('12:00:00');
    const [currentRadius, setCurrentRadius] = React.useState(1);

    React.useEffect(() => {
        const update = () => {
            const expansionMs = getDomainExpansionIntervalMs();
            const now = Date.now();
            const start = (typeof activatedAt === 'number' && activatedAt > 0) ? activatedAt : now;
            const elapsed = Math.max(0, now - start);
            const msUntilNext = expansionMs - (elapsed % expansionMs);

            const hours = Math.floor(msUntilNext / (1000 * 60 * 60));
            const mins = Math.floor((msUntilNext % (1000 * 60 * 60)) / (1000 * 60));
            const secs = Math.floor((msUntilNext % (1000 * 60)) / 1000);

            const formatted = `${String(hours).padStart(2, '0')}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
            const radius = Math.min(16, 1 + Math.floor(elapsed / expansionMs));

            setTimeLeft(formatted);
            setCurrentRadius(radius);
        };

        update();
        const interval = setInterval(update, 1000);
        return () => clearInterval(interval);
    }, [activatedAt]);

    return (
        <div style={{
            marginTop: '16px',
            padding: '14px 20px',
            background: 'linear-gradient(135deg, rgba(20, 15, 10, 0.9) 0%, rgba(10, 8, 6, 0.95) 100%)',
            border: '1px solid rgba(229, 181, 79, 0.4)',
            borderRadius: '12px',
            boxShadow: '0 4px 20px rgba(0, 0, 0, 0.6), inset 0 0 15px rgba(229, 181, 79, 0.1)',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: '6px'
        }}>
            <div style={{ fontSize: '11px', color: 'rgba(240, 237, 229, 0.7)', textTransform: 'uppercase', letterSpacing: '1.5px', fontFamily: "'Cinzel', serif" }}>
                NEXT DOMAIN EXPANSION ({currentRadius}-TILE RADIUS ACTIVE)
            </div>
            <div style={{
                fontSize: '24px',
                fontWeight: '800',
                fontFamily: "'Cinzel', 'Courier New', monospace",
                color: '#f9b115',
                letterSpacing: '3px',
                textShadow: '0 0 12px rgba(249, 177, 21, 0.6)'
            }}>
                {timeLeft}
            </div>
        </div>
    );
};

const getPstDate = () => {
    const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: 'America/Los_Angeles',
        year: 'numeric', month: 'numeric', day: 'numeric',
        hour: 'numeric', minute: 'numeric', second: 'numeric',
        hour12: false
    });
    const parts = formatter.formatToParts(new Date());
    const map = {};
    parts.forEach(p => map[p.type] = p.value);
    return new Date(map.year, map.month - 1, map.day, map.hour, map.minute, map.second);
};

const getPstDateFromIso = (isoString) => {
    if (!isoString) return new Date(0);
    const date = new Date(isoString);
    const formatter = new Intl.DateTimeFormat('en-US', {
        timeZone: 'America/Los_Angeles',
        year: 'numeric', month: 'numeric', day: 'numeric',
        hour: 'numeric', minute: 'numeric', second: 'numeric',
        hour12: false
    });
    const parts = formatter.formatToParts(date);
    const map = {};
    parts.forEach(p => map[p.type] = p.value);
    return new Date(map.year, map.month - 1, map.day, map.hour, map.minute, map.second);
};

const getLastRelockPst = (pstNow) => {
    if (pstNow.getHours() >= 12) {
        return new Date(pstNow.getFullYear(), pstNow.getMonth(), pstNow.getDate(), 12, 0, 0);
    } else {
        return new Date(pstNow.getFullYear(), pstNow.getMonth(), pstNow.getDate(), 0, 0, 0);
    }
};

const getNextRelockPst = (pstNow) => {
    const noon = new Date(pstNow.getFullYear(), pstNow.getMonth(), pstNow.getDate(), 12, 0, 0);
    const midnight = new Date(pstNow.getFullYear(), pstNow.getMonth(), pstNow.getDate() + 1, 0, 0, 0);
    if (pstNow < noon) {
        return noon;
    } else {
        return midnight;
    }
};

