    componentDidUpdate(prevProps, prevState) {
        if (this.props.boardManager) {
            this.props.boardManager.getPeerPlayers = () => this.state.peerPlayers;
            this.props.boardManager.handlePeerTileInteraction = (peer, coords) => this.handlePeerTileInteraction(peer, coords);
        }
        // Auto-scroll dev console output to bottom when new output is added
        if (
            this.state.devConsoleOpen &&
            this.devConsoleOutputRef &&
            this.devConsoleOutputRef.current &&
            prevState.devConsoleOutput !== this.state.devConsoleOutput
        ) {
            // Defer scroll to ensure DOM is updated with new output
            setTimeout(() => {
                const outputDiv = this.devConsoleOutputRef.current;
                if (outputDiv) {
                    outputDiv.scrollTop = outputDiv.scrollHeight;
                }
                if (
                    this.state.devConsoleOpen &&
                    this.devConsoleOutputRef &&
                    this.devConsoleOutputRef.current &&
                    prevState.devConsoleOutput !== this.state.devConsoleOutput
                ) {
                    // Defer scroll to ensure DOM is updated with new output
                    setTimeout(() => {
                        const outputDiv = this.devConsoleOutputRef.current;
                        if (outputDiv && outputDiv.lastElementChild) {
                            outputDiv.lastElementChild.scrollIntoView({ behavior: 'auto' });
                        }
                    }, 0);
                }
            }, 0);
        }
        if (this.state.inMonsterBattle && !prevState.inMonsterBattle) {
            this.wireMonsterBattleRefToWizardAI();
        }
        if (this.state.inMonsterBattle !== prevState.inMonsterBattle || this.state.inTowerSiege !== prevState.inTowerSiege) {
            if (this.state.inMonsterBattle || this.state.inTowerSiege) {
                document.body.classList.add('combat-active');
            } else {
                document.body.classList.remove('combat-active');
            }
        }
        if (
            (prevState.leftPanelExpanded !== this.state.leftPanelExpanded ||
                prevState.rightPanelExpanded !== this.state.rightPanelExpanded) &&
            this.props.boardManager &&
            this.props.boardManager.playerTile
        ) {
            const coords = this.props.boardManager.playerTile.location;
            if (coords) {
                this.checkMobileViewportCentering(coords, true);
            }
        }
        if (this.state.tiles !== prevState.tiles) {
            if (this.projectileCanvasRef && this.projectileCanvasRef.current) {
                this.projectileCanvasRef.current.clearProjectiles();
            }
        }
    }
